"""devcontainerでピン留めしたcargo開発ツールの更新を確認する。

Dependabotは`.devcontainer/Dockerfile`の`cargo install`行・`ARG`値や、
ワークフローの`tool: <crate>@<版>`（taiki-e/install-action）の中身を見ない。
このスクリプトで、ピン留めしたツールの新版と、DockerfileとCIのピンの食い違いを
検出する。`check_cargo_tool_updates.yml`から定期実行され、差分があればIssueの
本文に使うMarkdownを書き出す。

- 新版: ピン留め版 vs crates.ioの最新版（yankedとプレリリースを除く）。
- 食い違い: Dockerfileの`ARG`とワークフローの`tool:`で同じcrateの版が異なる
  （例: cargo-auditはDockerfileと`ci_engine.yml`で同じ版に揃える運用）。

標準ライブラリのみで動く（cargoのインストール不要）。標準出力には要約のみを出す。

使用例（リポジトリルートから）:
    python .github/scripts/check_cargo_tool_updates.py --output report.md
"""

from __future__ import annotations

import argparse
import json
import re
import sys
import urllib.request
from pathlib import Path

_REPO_ROOT = Path(__file__).resolve().parents[2]
_DOCKERFILE = _REPO_ROOT / ".devcontainer" / "Dockerfile"
_WORKFLOWS_DIR = _REPO_ROOT / ".github" / "workflows"

_CRATES_API_URL = "https://crates.io/api/v1/crates/{name}"
# crates.ioのAPIはUser-Agentの指定が必須（連絡先を含めるよう求められている）
_USER_AGENT = (
    "econometricsmodels-check-cargo-tool-updates "
    "(https://github.com/masahiroyecon1997dev/econometricsmodels)"
)

# `ARG CARGO_AUDIT_VERSION=0.22.2`（Dockerfileの書式）
_ARG_RE = re.compile(r"^ARG\s+(?P<arg>\w+)=(?P<ver>\S+)\s*$", re.MULTILINE)
# `cargo-audit@${CARGO_AUDIT_VERSION}`（`cargo install`行の書式）
_INSTALL_RE = re.compile(r"(?P<crate>[A-Za-z0-9_-]+)@\$\{(?P<arg>\w+)\}")
# `tool: cargo-audit@0.22.2`（カンマ区切りで複数指定もありうる）
_TOOL_RE = re.compile(r"^\s*tool:\s*(?P<spec>\S+)\s*(?:#.*)?$", re.MULTILINE)


def parse_dockerfile_pins(dockerfile_text: str) -> dict[str, str]:
    """Dockerfileの`cargo install`で使う`ARG`から、crate名→ピン留め版を取る。"""
    args = {m["arg"]: m["ver"] for m in _ARG_RE.finditer(dockerfile_text)}
    return {
        m["crate"]: args[m["arg"]]
        for m in _INSTALL_RE.finditer(dockerfile_text)
        if m["arg"] in args
    }


def parse_workflow_pins(workflow_text: str) -> dict[str, str]:
    """ワークフローの`tool: <crate>@<版>`から、crate名→ピン留め版を取る。"""
    pins = {}
    for m in _TOOL_RE.finditer(workflow_text):
        for item in m["spec"].split(","):
            crate, sep, ver = item.partition("@")
            if sep and ver:
                pins[crate] = ver
    return pins


def _version_key(version: str) -> tuple[int, ...]:
    return tuple(int(p) for p in version.split("."))


def latest_stable_version(api_json: dict) -> str | None:
    """crates.io APIの応答から、yankedとプレリリースを除く最新版を返す。"""
    stable = [
        v["num"]
        for v in api_json.get("versions", [])
        if not v.get("yanked") and re.fullmatch(r"\d+(?:\.\d+)*", v["num"])
    ]
    return max(stable, key=_version_key) if stable else None


def _fetch_json(url: str) -> dict:
    req = urllib.request.Request(url, headers={"User-Agent": _USER_AGENT})
    with urllib.request.urlopen(req, timeout=60) as resp:
        return json.loads(resp.read().decode("utf-8"))


def render_report(
    outdated: dict[str, tuple[str, str]],
    drifted: dict[str, tuple[str, str]],
    missing: list[str],
) -> str:
    """Issue本文（英語・公開リポジトリのため）のMarkdownを組み立てる。"""
    lines = [
        (
            "Automatically generated by the `Check cargo tool updates` "
            "workflow (`.github/workflows/check_cargo_tool_updates.yml`). "
            "This issue is updated on every run and closed automatically "
            "once everything is up to date."
        ),
        "",
    ]
    if outdated:
        lines += [
            "## Newer releases on crates.io",
            "",
            "| Crate | Pinned | crates.io latest |",
            "|---|---|---|",
        ]
        lines += [
            f"| `{crate}` | {pinned} | {latest} |"
            for crate, (pinned, latest) in sorted(outdated.items())
        ]
        lines.append("")
    if drifted:
        lines += [
            "## Dockerfile and CI pins disagree",
            "",
            "| Crate | `.devcontainer/Dockerfile` | CI workflow `tool:` |",
            "|---|---|---|",
        ]
        lines += [
            f"| `{crate}` | {docker} | {ci} |"
            for crate, (docker, ci) in sorted(drifted.items())
        ]
        lines.append("")
    if missing:
        names = ", ".join(f"`{c}`" for c in sorted(missing))
        lines += [
            "## Pinned crates without a stable release on crates.io",
            "",
            f"Check these manually: {names}",
            "",
        ]
    lines += [
        "## How to update",
        "",
        (
            "1. Bump the `ARG` value in `.devcontainer/Dockerfile` and, for "
            "`cargo-audit`, the `tool: cargo-audit@<version>` pin in "
            "`.github/workflows/ci_engine.yml` (keep the two identical)."
        ),
        "2. Rebuild the devcontainer image.",
        (
            "3. Re-run `cargo audit` (and `cargo llvm-cov -p engine` / "
            "`cargo about` if those tools changed) and review the output."
        ),
    ]
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--output",
        type=Path,
        help="更新があるときにIssue本文のMarkdownを書き出すパス",
    )
    args = parser.parse_args()

    docker_pins = parse_dockerfile_pins(
        _DOCKERFILE.read_text(encoding="utf-8")
    )
    if not docker_pins:
        print("ERROR: no pinned cargo tools found in Dockerfile")
        return 2

    ci_pins: dict[str, str] = {}
    for path in sorted(_WORKFLOWS_DIR.glob("*.yml")):
        ci_pins.update(parse_workflow_pins(path.read_text(encoding="utf-8")))

    # DockerfileにもCIにもあるcrateは版が一致していること。CIだけにある
    # ピンも最新版の確認対象に含める（更新漏れの見落とし防止）。
    drifted = {
        crate: (docker_pins[crate], ci_pins[crate])
        for crate in docker_pins.keys() & ci_pins.keys()
        if _version_key(docker_pins[crate]) != _version_key(ci_pins[crate])
    }
    pinned = {**ci_pins, **docker_pins}

    outdated: dict[str, tuple[str, str]] = {}
    missing = []
    for crate, ver in pinned.items():
        latest = latest_stable_version(
            _fetch_json(_CRATES_API_URL.format(name=crate))
        )
        if latest is None:
            missing.append(crate)
        elif _version_key(latest) != _version_key(ver):
            outdated[crate] = (ver, latest)

    print(
        f"pinned={len(pinned)} outdated={len(outdated)} "
        f"drifted={len(drifted)} missing={len(missing)}"
    )
    for crate, (ver, latest) in sorted(outdated.items()):
        print(f"  {crate}: {ver} -> {latest}")
    for crate, (docker, ci) in sorted(drifted.items()):
        print(f"  {crate}: Dockerfile {docker} != CI {ci}")

    if outdated or drifted or missing:
        if args.output:
            args.output.write_text(
                render_report(outdated, drifted, missing), encoding="utf-8"
            )
            print(f"report written: {args.output}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
